import { Router } from '@angular/router';
import { inject } from '@angular/core';
import { AuthService } from '../services/auth.service';
/**
 * Route guard: allows access to admin routes when the user is logged in and has an
 * authorized admin-level role — the platform super admin (ADMIN) or a tenant
 * organization admin (INSTITUTE_ADMIN). The granular tenant/org authorization for the
 * actual data endpoints is enforced by the backend; this guard only opens the portal
 * layout for the two admin tiers.
 */
const ADMIN_ROLES = ['ADMIN', 'INSTITUTE_ADMIN'];
export const adminGuard = () => {
  const auth = inject(AuthService);
  const router = inject(Router);
  const u = auth.user;
  const hasAdminRole = !!u && ADMIN_ROLES.some(r => (u.roles ?? []).includes(r) || u.role === r);
  if (auth.isLoggedIn() && hasAdminRole) {
    return true;
  }
  router.navigate(['/login']);
  return false;
};
/**
 * Super-admin-only guard: blocks everyone except the platform super admin (ADMIN role)
 * from routes exclusive to the platform owner \u2014 Organizations, Org Subscriptions.
 * Org admins (INSTITUTE_ADMIN) and faculty are redirected to the dashboard.
 */
export const adminOnlyGuard = () => {
  const auth = inject(AuthService);
  const router = inject(Router);
  if (auth.isLoggedIn() && auth.isAdmin) {
    return true;
  }
  router.navigate(['/']);
  return false;
};
/**
 * Allows anyone who administers an organization — the platform super admin or a
 * tenant's own INSTITUTE_ADMIN. Used for the Account page, which both need: the
 * tenant to manage their own subscription, and the platform admin to see exactly what
 * the customer sees when supporting them.
 *
 * <p>Deliberately a ROLE check. The platform-versus-tenant menu split elsewhere keys
 * off the hostname, and in local development every host resolves to the platform
 * domain — so a hostname-based rule would hide the Account page from precisely the
 * users it is built for whenever they are not on a production subdomain.
 */
export const orgAdminGuard = () => {
  const auth = inject(AuthService);
  const router = inject(Router);
  const u = auth.user;
  const hasRole = !!u && ADMIN_ROLES.some(r => (u.roles ?? []).includes(r) || u.role === r);
  if (auth.isLoggedIn() && (hasRole || auth.isAdmin)) {
    return true;
  }
  router.navigate(['/']);
  return false;
};
